UPDATE t_p96441965_look_app_redesign.app_settings
SET value = replace(value, 'Яндекс SpeechKit — расшифровка голосовых сообщений в чатах;' || chr(10), 'Яндекс SpeechKit — расшифровка голосовых сообщений в чатах;' || chr(10) || 'Яндекс.Метрика — статистика посещений сайта (обезличенные данные о визитах: IP-адрес, тип устройства и браузера);' || chr(10) || 'MyMemory — перевод текстов и комментариев по вашему запросу (сервису передаётся только переводимый текст);' || chr(10))
WHERE key = 'privacy_policy' AND position('MyMemory' in value) = 0;